        texte = compte + " " + ip
        if ip not in connues.get(compte, []) and texte not in resultat:
            resultat.append(texte)
    return resultat

import ipaddress

def alertes(journal, connues):
    resultat = []
    for ligne in journal:
        date, heure, statut, compte, ip = ligne.split()
        if statut != "SUCCES":
            continue
        raisons = []
        h = int(heure.split(":")[0])
        if h < 7 or h >= 19:
            raisons.append("hors horaires")
        if ip not in connues.get(compte, []):
            raisons.append("IP inconnue")
        if not ipaddress.ip_address(ip).is_private:
            raisons.append("IP publique")
        if raisons:
            resultat.append(compte + " " + heure + " : " + ", ".join(raisons))
    return resultat
